std::string decoded;
std::shared_ptr<Node> current = root;
int bits_read = 0;
char byte;
while (infile.get(byte) && bits_read < encoded_length) {
    for (int i = 7; i >= 0 && bits_read < encoded_length; --i) {
        bool bit = (byte >> i) & 1;
        if (bit) {
            current = current->right;
        } else {
            current = current->left;
        }
        if (!current->left && !current->right) {
            decoded += current->symbol;
            current = root;
        }
        ++bits_read;
    }
}
return decoded;
// END_CODE

